const lv_image_dsc_t * icon_get(const char * name, int size)
{
    if (name == NULL) return NULL;

    for (size_t i = 0; i < sizeof(icon_table) / sizeof(icon_table[0]); i++) {
        if (strcmp(icon_table[i].name, name) == 0) {
            return (size >= 32) ? icon_table[i].dsc_48 : icon_table[i].dsc_24;
        }
    }
    return NULL;
}
